function cheapestDescent(pyramid: number[][]): number {
  const n = pyramid.length;
  const go = (i: number, j: number): number =>
    i === n - 1 ? pyramid[i][j] : pyramid[i][j] + Math.min(go(i + 1, j), go(i + 1, j + 1));
  return go(0, 0);
}

