function cheapestDescent(pyramid: number[][]): number {
  const n = pyramid.length;
  const reach: number[][] = [[pyramid[0][0]]];
  for (let i = 1; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j <= i; j++) {
      const fromLeft = j > 0 ? reach[i - 1][j - 1] : Infinity;
      const fromAbove = j < i ? reach[i - 1][j] : Infinity;
      row.push(pyramid[i][j] + Math.min(fromLeft, fromAbove));
    }
    reach.push(row);
  }
  return Math.min(...reach[n - 1]);
}

