class Solution:
    def cheapestDescent(self, pyramid: List[List[int]]) -> int:
        reach = [pyramid[0][:]]
        for i in range(1, len(pyramid)):
            prev = reach[-1]
            row = []
            for j in range(i + 1):
                from_left = prev[j - 1] if j > 0 else float("inf")
                from_above = prev[j] if j < i else float("inf")
                row.append(pyramid[i][j] + min(from_left, from_above))
            reach.append(row)
        return min(reach[-1])

