function cheapestDescent(pyramid: number[][]): number {
  const best = pyramid[pyramid.length - 1].slice();
  for (let i = pyramid.length - 2; i >= 0; i--) {
    for (let j = 0; j <= i; j++) {
      best[j] = pyramid[i][j] + Math.min(best[j], best[j + 1]);
    }
  }
  return best[0];
}

